import { Component, EventEmitter, Input, Output } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';

import { ReferenciaPersonal } from '../../../models/referencia.personal.model';
import { ReferenciaPersonalService } from '../../../controllers/referencia.personal.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';
import { FormField } from '../../../shared/generic-form/form-field/form-field.component';

export const REFERENCIA_PERSONAL_FORM:FormField[]=[
  {
    key:'nombre',
    label:'Nombre',
    type:'text'
  },
  {
    key:'parentezco',
    label:'Parentesco',
    apiUrl:'api/parentesco',
    keyList:'id',
    keyDetalle:'nombre',
    nuevoRedirect:'/catalogos/parentescos/nuevo'
  },
  {
    key:'telefono',
    label:'Telefono',
    type:'text'
  },
  {
    key:'domicilio',
    label:'Domicilio',
    style:{
      div:'col-12 col-sm p-3'
    },
    type:'text'
  },
]

@Component({
    selector: 'app-form-referencias-personales',
    imports: [
    GenericFormComponent
],
    templateUrl: './form-referencias-personales.component.html',
    styleUrl: './form-referencias-personales.component.css'
})
export class FormReferenciasPersonalesComponent {
  form= REFERENCIA_PERSONAL_FORM
  @Input() edit?:ReferenciaPersonal
  @Output() editChange = new EventEmitter<ReferenciaPersonal>()

  constructor(
    public referenciaPersonalController: ReferenciaPersonalService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id = this.utils.intOrNull(params.get('id'))
      if(id){
        this.edit= await this.referenciaPersonalController.find(id)
      }
    })
  }
}
